INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-believe', 'believe', '/bɪˈliːv/', 'verb', 'to think something is true', '相信', 'To believe is to think something is true.', '相信就是认为某件事是真的。', '[{"en":"I believe we can finish it.","zh":"我相信我们能完成它。"},{"en":"She believes the box is strong.","zh":"她相信这个盒子很结实。"}]', NULL, '💭', 3, '["core","abstract"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explain', 'explain', '/ɪkˈspleɪn/', 'verb', 'to make something clear', '解释', 'To explain is to make something clear.', '解释就是把事情说清楚。', '[{"en":"Please explain your idea.","zh":"请解释你的想法。"},{"en":"He explains how the machine works.","zh":"他解释这台机器怎么运作。"}]', NULL, '💬', 3, '["core","action"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-improve', 'improve', '/ɪmˈpruːv/', 'verb', 'to make something better', '改进', 'To improve is to make something better.', '改进就是把东西变得更好。', '[{"en":"We improve our treehouse.","zh":"我们改进我们的树屋。"},{"en":"Paint can improve an old box.","zh":"颜料可以让旧盒子变好看。"}]', NULL, '📈', 3, '["core","action"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-together', 'together', '/təˈɡeðə/', 'adverb', 'with another person or in a group', '一起', 'Together means with another person or in a group.', '一起就是和别人或一群人共同做一件事。', '[{"en":"We build the treehouse together.","zh":"我们一起建造树屋。"},{"en":"The friends play together.","zh":"朋友们一起玩。"}]', NULL, '🤝', 3, '["core","abstract","emotional"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-happy', 'happy', '/ˈhæpi/', 'adjective', 'feeling good', '开心的', 'Happy means feeling good.', '开心就是感觉很好。', '[{"en":"I am happy with my picture.","zh":"我对我的画很满意。"},{"en":"The children are happy to build together.","zh":"孩子们一起搭建很开心。"}]', NULL, '😊', 1, '["core","emotional"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-excited', 'excited', '/ɪkˈsaɪtɪd/', 'adjective', 'feeling full of energy about something', '兴奋的', 'Excited means feeling full of energy about something.', '兴奋就是为某件事特别高兴、特别有精神。', '[{"en":"We are excited about the project.","zh":"我们对这个项目很兴奋。"},{"en":"She is excited to start.","zh":"她兴奋地准备开始。"}]', NULL, '🤩', 3, '["core","emotional"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-worried', 'worried', '/ˈwʌrid/', 'adjective', 'feeling that something bad may happen', '担心的', 'Worried means feeling that something bad may happen.', '担心就是觉得可能会有不好的事发生。', '[{"en":"She is worried about the mess.","zh":"她担心弄得一团糟。"},{"en":"Do not be worried; we can fix it.","zh":"别担心，我们能修好。"}]', NULL, '😟', 3, '["core","emotional"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-brave', 'brave', '/breɪv/', 'adjective', 'not afraid to try', '勇敢的', 'Brave means not afraid to try.', '勇敢就是不怕尝试。', '[{"en":"He is brave and tries again.","zh":"他很勇敢，又试了一次。"},{"en":"Be brave and show your design.","zh":"勇敢一点，展示你的设计。"}]', NULL, '🦸', 2, '["core","emotional"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-clever', 'clever', '/ˈklevə/', 'adjective', 'good at thinking and making things', '聪明的', 'Clever means good at thinking and making things.', '聪明就是很会思考和做东西。', '[{"en":"She is clever with boxes.","zh":"她很会用盒子做东西。"},{"en":"That is a clever idea.","zh":"那是个聪明的主意。"}]', NULL, '🧠', 2, '["core","emotional"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-kind', 'kind', '/kaɪnd/', 'adjective', 'nice and helpful to others', '友善的', 'Kind means nice and helpful to others.', '友善就是对别人很好、乐于帮忙。', '[{"en":"It is kind to help.","zh":"帮助别人是友善的。"},{"en":"Our teacher is kind.","zh":"我们的老师很友善。"}]', NULL, '💛', 3, '["core","emotional"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-friendly', 'friendly', '/ˈfrendli/', 'adjective', 'nice and easy to talk to', '友好的', 'Friendly means nice and easy to talk to.', '友好就是对人亲切、容易相处。', '[{"en":"The teacher is friendly.","zh":"老师很友好。"},{"en":"The new child is friendly.","zh":"新来的孩子很友好。"}]', NULL, '🤗', 3, '["core","emotional"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-beautiful', 'beautiful', '/ˈbjuːtɪfl/', 'adjective', 'very nice to look at', '美丽的', 'Beautiful means very nice to look at.', '美丽就是看起来很好看。', '[{"en":"My picture is beautiful.","zh":"我的画很美丽。"},{"en":"We make a beautiful card.","zh":"我们做了一张美丽的卡片。"}]', NULL, '🌟', 1, '["core","abstract"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-important', 'important', '/ɪmˈpɔːtnt/', 'adjective', 'matters a lot', '重要的', 'Important means that it matters a lot.', '重要就是很要紧。', '[{"en":"It is important to be careful.","zh":"小心很重要。"},{"en":"Sleep is important for children.","zh":"睡眠对孩子很重要。"}]', NULL, '❗', 3, '["core","abstract"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-ready', 'ready', '/ˈredi/', 'adjective', 'prepared to start', '准备好的', 'Ready means prepared to start.', '准备好就是可以开始了。', '[{"en":"We are ready to start.","zh":"我们准备好开始了。"},{"en":"The paint is ready to use.","zh":"颜料准备好可以用了。"}]', NULL, '🏁', 3, '["core","abstract"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-01', 'beach', '/biːtʃ/', 'noun', 'the sand next to the sea', '海滩；沙滩', 'You can walk on the sand next to the water.', '你可以在水边的沙子上散步。', '[{"en":"We play on the beach.","zh":"我们在海滩上玩。"},{"en":"The beach is warm today.","zh":"今天沙滩上很暖和。"}]', NULL, '🏖️', 1, '["core","place"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-02', 'sea', '/siː/', 'noun', 'the big water with salt in it', '大海', 'Fish live in the sea, and it is very big.', '鱼生活在大海里，大海非常大。', '[{"en":"The sea is blue.","zh":"大海是蓝色的。"},{"en":"We can see the sea from here.","zh":"我们从这里能看到大海。"}]', NULL, '🌊', 1, '["core","nature"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-03', 'tree', '/triː/', 'noun', 'a tall plant with a trunk and leaves', '树', 'A tree has a trunk and many leaves.', '树有树干和许多叶子。', '[{"en":"The tree is very tall.","zh":"这棵树很高。"},{"en":"A bird is in the tree.","zh":"一只鸟在树上。"}]', NULL, '🌳', 1, '["core","nature"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-04', 'flower', '/ˈflaʊə/', 'noun', 'a pretty plant part that smells nice', '花', 'A flower is pretty and can smell nice.', '花很漂亮，还可能有香味。', '[{"en":"This flower is pink.","zh":"这朵花是粉色的。"},{"en":"I put a flower in a glass.","zh":"我把一朵花放进杯子里。"}]', NULL, '🌸', 1, '["core","nature"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-05', 'garden', '/ˈɡɑːdn/', 'noun', 'a place where plants grow', '花园', 'You grow flowers and plants in a garden.', '你在花园里种花和植物。', '[{"en":"Our garden has many flowers.","zh":"我们的花园里有很多花。"},{"en":"Dad works in the garden.","zh":"爸爸在花园里干活。"}]', NULL, '🌷', 1, '["core","place"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-06', 'animal', '/ˈænɪml/', 'noun', 'a living thing that is not a plant', '动物', 'An animal can move and eat. A dog is an animal.', '动物会动也会吃东西。狗就是一种动物。', '[{"en":"An animal lives in the forest.","zh":"一只动物住在森林里。"},{"en":"The cat is a small animal.","zh":"猫是一种小动物。"}]', NULL, '🐾', 1, '["core","animal"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-07', 'bird', '/bɜːd/', 'noun', 'an animal with wings and feathers', '鸟', 'A bird has wings and can fly.', '鸟有翅膀，会飞。', '[{"en":"A bird is singing.","zh":"一只鸟在唱歌。"},{"en":"That bird has blue wings.","zh":"那只鸟有蓝色的翅膀。"}]', NULL, '🐦', 1, '["core","animal"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-08', 'shell', '/ʃel/', 'noun', 'a hard cover that some animals live in', '贝壳', 'You can find a shell on the beach.', '你可以在海滩上找到贝壳。', '[{"en":"I found a shell on the sand.","zh":"我在沙滩上找到一个贝壳。"},{"en":"This shell is pink.","zh":"这个贝壳是粉色的。"}]', NULL, '🐚', 1, '["core","object"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-09', 'sun', '/sʌn/', 'noun', 'the bright light in the sky during the day', '太阳', 'The sun gives us light and makes the day warm.', '太阳给我们光，让白天变得温暖。', '[{"en":"The sun is bright today.","zh":"今天太阳很亮。"},{"en":"The sun is in the sky.","zh":"太阳在天空中。"}]', NULL, '☀️', 1, '["core","nature"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-10', 'boat', '/bəʊt/', 'noun', 'a small thing that floats and carries people on water', '小船', 'You can ride in a boat on the water.', '你可以坐小船在水上走。', '[{"en":"The boat is on the lake.","zh":"小船在湖上。"},{"en":"We go in a boat.","zh":"我们坐小船。"}]', NULL, '⛵', 1, '["core","object"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-11', 'river', '/ˈrɪvə/', 'noun', 'a long line of water that moves to the sea', '河流', 'Water moves along a river to the sea.', '水沿着河流向大海流去。', '[{"en":"The river is long and blue.","zh":"这条河又长又蓝。"},{"en":"Fish swim in the river.","zh":"鱼在河里游。"}]', NULL, '🏞️', 2, '["core","nature"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-12', 'forest', '/ˈfɒrɪst/', 'noun', 'a big place with many trees', '森林', 'Many trees grow together in a forest.', '许多树长在一起，就是森林。', '[{"en":"We walk in the forest.","zh":"我们在森林里散步。"},{"en":"The forest is quiet.","zh":"森林里很安静。"}]', NULL, '🌲', 2, '["core","place"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-13', 'mountain', '/ˈmaʊntən/', 'noun', 'a very high hill', '山；高山', 'A mountain is very high and made of rock.', '山很高，由岩石组成。', '[{"en":"The mountain is high.","zh":"这座山很高。"},{"en":"We climb the mountain.","zh":"我们爬山。"}]', NULL, '⛰️', 2, '["core","nature"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-14', 'island', '/ˈaɪlənd/', 'noun', 'land with water all around it', '岛', 'An island has water all around it.', '岛的四周都是水。', '[{"en":"The island is small.","zh":"这个岛很小。"},{"en":"We take a boat to the island.","zh":"我们坐船去岛上。"}]', NULL, '🏝️', 2, '["core","place"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-15', 'lake', '/leɪk/', 'noun', 'a big pool of water with land around it', '湖', 'A lake is water with land all around it.', '湖是四周被陆地围住的水。', '[{"en":"The lake is calm today.","zh":"今天湖面很平静。"},{"en":"We swim in the lake.","zh":"我们在湖里游泳。"}]', NULL, '💧', 2, '["core","nature"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-16', 'rock', '/rɒk/', 'noun', 'a hard piece of stone', '岩石；石头', 'A rock is hard and comes from the ground.', '岩石很硬，来自地下。', '[{"en":"I sit on a big rock.","zh":"我坐在一块大石头上。"},{"en":"The rock is heavy.","zh":"这块石头很重。"}]', NULL, '🪨', 2, '["core","material"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-17', 'grass', '/ɡrɑːs/', 'noun', 'short green plants that cover the ground', '草', 'Grass is green and grows on the ground.', '草是绿色的，长在地上。', '[{"en":"The grass is green.","zh":"草是绿色的。"},{"en":"We sit on the grass.","zh":"我们坐在草地上。"}]', NULL, '🌿', 2, '["core","nature"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-18', 'storm', '/stɔːm/', 'noun', 'strong wind and rain', '暴风雨', 'A storm has strong wind and a lot of rain.', '暴风雨有很大的风和很多雨。', '[{"en":"The storm is loud.","zh":"暴风雨很响。"},{"en":"We stay inside during the storm.","zh":"暴风雨时我们待在屋里。"}]', NULL, '⛈️', 3, '["thematic","weather"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-19', 'cave', '/keɪv/', 'noun', 'a big hole in a hill or rock', '山洞；洞穴', 'A cave is a dark hole in a hill or under the ground.', '山洞是山里的黑洞，或者地下的洞。', '[{"en":"The cave is dark.","zh":"山洞里很黑。"},{"en":"We look inside the cave.","zh":"我们往山洞里看。"}]', NULL, '🕳️', 3, '["thematic","place"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-20', 'wonderful', '/ˈwʌndəfl/', 'adjective', 'very good and making you feel happy', '美妙的；很棒的', 'Something wonderful is very good and makes you smile.', '美妙的事物非常好，会让你笑起来。', '[{"en":"The view is wonderful.","zh":"这里的景色美极了。"},{"en":"We had a wonderful day.","zh":"我们度过了美好的一天。"}]', NULL, '✨', 3, '["core","abstract","emotional"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-01', 'map', '/mæp/', 'noun', 'a picture that shows where places are', '地图', 'A map shows you where places are.', '地图告诉你各个地方在哪里。', '[{"en":"Look at the map.","zh":"看看地图。"},{"en":"The map shows the river.","zh":"地图上画着这条河。"}]', NULL, '🗺️', 2, '["thematic","object"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-02', 'between', '/bɪˈtwiːn/', 'preposition', 'in the space in the middle of two things', '在……之间', 'When something is between two things, it is in the middle.', '一个东西在两个东西中间，就是在它们之间。', '[{"en":"The gate is between two trees.","zh":"大门在两棵树之间。"},{"en":"I sit between Mum and Dad.","zh":"我坐在妈妈和爸爸中间。"}]', NULL, '↔️', 1, '["core","direction"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-03', 'road', '/rəʊd/', 'noun', 'a hard way for cars to travel', '路；马路', 'Cars and buses drive on a road.', '汽车和公共汽车在马路上行驶。', '[{"en":"The road goes to the village.","zh":"这条路通向村子。"},{"en":"Look before you cross the road.","zh":"过马路前要看看。"}]', NULL, '🛣️', 2, '["core","place"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-04', 'travel', '/ˈtrævl/', 'verb', 'to go from one place to another', '旅行', 'When you travel, you go to another place.', '旅行就是去另一个地方。', '[{"en":"We travel by train.","zh":"我们坐火车旅行。"},{"en":"I want to travel around the world.","zh":"我想环游世界。"}]', NULL, '🧳', 2, '["core","action"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-05', 'climb', '/klaɪm/', 'verb', 'to go up something', '爬；攀登', 'When you climb, you go up a hill or a tree.', '爬，就是往山上或树上走。', '[{"en":"We climb the hill.","zh":"我们爬上山。"},{"en":"Can you climb that tree?","zh":"你能爬上那棵树吗？"}]', NULL, '🧗', 2, '["core","action"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-06', 'around', '/əˈraʊnd/', 'preposition', 'on every side of something', '围绕；在……周围', 'When you go around something, you go from one side to the other.', '绕着某个东西走，就是从一边走到另一边。', '[{"en":"We walk around the lake.","zh":"我们绕着湖走。"},{"en":"Look around you.","zh":"看看你的四周。"}]', NULL, '🔄', 2, '["core","direction"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-07', 'near', '/nɪə/', 'preposition', 'not far away', '靠近；在……附近', 'If something is near, it is close to you.', '如果某个东西很近，它就在你旁边。', '[{"en":"The river is near our house.","zh":"河离我们家很近。"},{"en":"Sit near the fire.","zh":"坐在火堆旁边。"}]', NULL, '📍', 2, '["core","direction"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-08', 'up', '/ʌp/', 'adverb', 'to a higher place', '向上', 'When you go up, you go to a higher place.', '向上走，就是去更高的地方。', '[{"en":"We walk up the hill.","zh":"我们往山上走。"},{"en":"Look up at the sky.","zh":"抬头看天空。"}]', NULL, '⬆️', 2, '["core","direction"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-09', 'down', '/daʊn/', 'adverb', 'to a lower place', '向下', 'When you go down, you go to a lower place.', '向下走，就是去更低的地方。', '[{"en":"We go down the path.","zh":"我们沿着小路往下走。"},{"en":"The sun goes down in the evening.","zh":"傍晚太阳落山。"}]', NULL, '⬇️', 2, '["core","direction"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-10', 'path', '/pɑːθ/', 'noun', 'a narrow way for walking', '小路', 'A path is a small way where people walk.', '小路是人们走路的小道。', '[{"en":"The path goes through the forest.","zh":"小路穿过森林。"},{"en":"Follow the path to the lake.","zh":"沿着小路走到湖边。"}]', NULL, '🥾', 3, '["thematic","place"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-11', 'bridge', '/brɪdʒ/', 'noun', 'something built over water or a road so people can cross', '桥', 'A bridge goes over water or a road.', '桥架在水面或道路上方。', '[{"en":"We walk across the bridge.","zh":"我们走过桥。"},{"en":"The bridge is made of stone.","zh":"这座桥是石头做的。"}]', NULL, '🌉', 3, '["core","place"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-12', 'gate', '/ɡeɪt/', 'noun', 'a door in a wall or fence', '大门', 'A gate is a door in a wall or fence.', '大门是墙或栅栏上的一扇门。', '[{"en":"The gate is open.","zh":"大门开着。"},{"en":"Please close the gate.","zh":"请把大门关上。"}]', NULL, '🚪', 3, '["core","object"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-13', 'torch', '/tɔːtʃ/', 'noun', 'a small light you can carry', '手电筒', 'A torch gives light when it is dark.', '天黑的时候，手电筒能照亮。', '[{"en":"Take a torch into the cave.","zh":"带一把手电筒进山洞。"},{"en":"My torch is bright.","zh":"我的手电筒很亮。"}]', NULL, '🔦', 3, '["thematic","tool"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
