INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-15', 'across', '/əˈkrɒs/', 'preposition', 'from one side to the other', '穿过；横过', 'When you go across, you go from one side to the other.', '穿过，就是从一边走到另一边。', '[{"en":"We walk across the field.","zh":"我们走过田野。"},{"en":"She swims across the lake.","zh":"她游过湖面。"}]', NULL, '➡️', 3, '["core","direction"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-16', 'follow', '/ˈfɒləʊ/', 'verb', 'to go after someone', '跟随', 'When you follow someone, you go behind them.', '跟随别人，就是跟在他后面走。', '[{"en":"Follow me to the river.","zh":"跟我到河边。"},{"en":"We follow the path.","zh":"我们沿着小路走。"}]', NULL, '👣', 3, '["core","action"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-17', 'turn', '/tɜːn/', 'verb', 'to move in a different direction', '转弯；转向', 'When you turn, you move to another way.', '转弯，就是换一个方向走。', '[{"en":"Turn left at the gate.","zh":"在大门那里向左转。"},{"en":"The road turns near the river.","zh":"路在河边拐弯。"}]', NULL, '↩️', 3, '["core","action"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-18', 'journey', '/ˈdʒɜːni/', 'noun', 'a long trip from one place to another', '旅程', 'A journey is a trip to another place.', '旅程就是去另一个地方的一段路。', '[{"en":"The journey takes two days.","zh":"这段旅程要两天。"},{"en":"We had a long journey home.","zh":"我们回家的路很长。"}]', NULL, '🛤️', 3, '["thematic","abstract"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-19', 'adventure', '/ədˈventʃə/', 'noun', 'an exciting thing to do or see', '冒险', 'An adventure is exciting and new.', '冒险是让人兴奋的新鲜事。', '[{"en":"Our trip was a big adventure.","zh":"我们的旅行是一次大冒险。"},{"en":"She loves adventure.","zh":"她喜欢冒险。"}]', NULL, '🧭', 3, '["thematic","abstract"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-20', 'explore', '/ɪkˈsplɔː/', 'verb', 'to look around a new place', '探索', 'When you explore, you look around a new place.', '探索就是在一个新地方到处看看。', '[{"en":"We explore the forest.","zh":"我们探索森林。"},{"en":"Let''s explore the cave.","zh":"我们去山洞里看看吧。"}]', NULL, '🔍', 3, '["thematic","action"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-01', 'story', '/ˈstɔːri/', 'noun', 'words that tell about people and things that happen', '故事', 'A story tells what happens to someone.', '故事讲的是某个人遇到了什么事。', '[{"en":"Dad reads me a story.","zh":"爸爸给我读故事。"},{"en":"This story is about a bird.","zh":"这个故事讲的是一只鸟。"}]', NULL, '📖', 1, '["core","object"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-02', 'robot', '/ˈrəʊbɒt/', 'noun', 'a machine that can move and do jobs', '机器人', 'A robot is a machine that can do things by itself.', '机器人是一种能自己干活的机器。', '[{"en":"The robot can walk.","zh":"这个机器人会走路。"},{"en":"I draw a robot.","zh":"我画了一个机器人。"}]', NULL, '🤖', 1, '["core","object"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-03', 'machine', '/məˈʃiːn/', 'noun', 'a thing with parts that works to do a job', '机器', 'A machine has parts that move and work together.', '机器有很多零件一起转动、一起干活。', '[{"en":"This machine washes clothes.","zh":"这台机器能洗衣服。"},{"en":"The machine is very big.","zh":"这台机器很大。"}]', NULL, '⚙️', 2, '["core","object"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-04', 'treasure', '/ˈtreʒə/', 'noun', 'gold, jewels, or other special things you find', '宝藏', 'Treasure is something special that people look for.', '宝藏是人们寻找的特别的东西。', '[{"en":"We found treasure in the cave.","zh":"我们在山洞里找到了宝藏。"},{"en":"The box is full of treasure.","zh":"盒子里装满了宝物。"}]', NULL, '💎', 2, '["thematic","object"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-05', 'planet', '/ˈplænɪt/', 'noun', 'a big round world in space', '行星', 'A planet is a big round world that goes around a star.', '行星是一颗绕着恒星转的大圆球。', '[{"en":"Earth is our planet.","zh":"地球是我们的行星。"},{"en":"Mars is a red planet.","zh":"火星是一颗红色的行星。"}]', NULL, '🪐', 3, '["thematic","nature"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-06', 'dinosaur', '/ˈdaɪnəsɔː/', 'noun', 'a very big animal that lived long ago', '恐龙', 'Dinosaurs were big animals that lived long ago.', '恐龙是很久以前生活的大动物。', '[{"en":"The dinosaur is very big.","zh":"这只恐龙很大。"},{"en":"I like dinosaur books.","zh":"我喜欢恐龙书。"}]', NULL, '🦕', 3, '["thematic","animal"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-07', 'learn', '/lɜːn/', 'verb', 'to find out something new', '学习；学会', 'When you learn, you find out something new.', '学习就是发现新的事情。', '[{"en":"We learn about animals.","zh":"我们学习关于动物的知识。"},{"en":"I learn a new word every day.","zh":"我每天学一个新单词。"}]', NULL, '🧠', 1, '["core","action"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-08', 'find', '/faɪnd/', 'verb', 'to see something you were looking for', '找到', 'When you find something, you see it after looking for it.', '找到，就是找了一会儿之后看见了它。', '[{"en":"I find a shell on the beach.","zh":"我在海滩上找到一个贝壳。"},{"en":"Can you find the map?","zh":"你能找到地图吗？"}]', NULL, '🔎', 1, '["core","action"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-09', 'look', '/lʊk/', 'verb', 'to use your eyes', '看', 'When you look, you use your eyes to see.', '看，就是用眼睛去瞧。', '[{"en":"Look at the stars.","zh":"看那些星星。"},{"en":"I look out of the window.","zh":"我看向窗外。"}]', NULL, '👀', 1, '["core","action"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-10', 'listen', '/ˈlɪsn/', 'verb', 'to hear something carefully', '听', 'When you listen, you try to hear a sound.', '听，就是用心去听一个声音。', '[{"en":"Listen to the birds.","zh":"听鸟儿叫。"},{"en":"I listen to a story.","zh":"我听故事。"}]', NULL, '👂', 1, '["core","action"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-11', 'ask', '/ɑːsk/', 'verb', 'to say a question', '问', 'When you ask, you say a question.', '问，就是说一个问题。', '[{"en":"I ask my teacher a question.","zh":"我问老师一个问题。"},{"en":"Ask him where the path is.","zh":"问问他小路在哪里。"}]', NULL, '❓', 1, '["core","action"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-12', 'show', '/ʃəʊ/', 'verb', 'to let someone see something', '给……看；展示', 'When you show something, you let someone see it.', '展示，就是让别人看到它。', '[{"en":"Show me your map.","zh":"给我看看你的地图。"},{"en":"I show my drawing to Mum.","zh":"我把画给妈妈看。"}]', NULL, '👋', 1, '["core","action"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-13', 'try', '/traɪ/', 'verb', 'to do your best to do something', '尝试；努力', 'When you try, you do your best.', '尝试，就是尽你最大的努力去做。', '[{"en":"I try to climb the tree.","zh":"我试着爬上那棵树。"},{"en":"Try again.","zh":"再试一次。"}]', NULL, '💪', 1, '["core","action"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-14', 'think', '/θɪŋk/', 'verb', 'to use your mind to make ideas', '想；思考', 'When you think, you use your mind.', '思考，就是用你的头脑。', '[{"en":"I think about the sea.","zh":"我想着大海。"},{"en":"Think before you answer.","zh":"回答前先想一想。"}]', NULL, '💭', 2, '["core","action"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-15', 'remember', '/rɪˈmembə/', 'verb', 'to keep something in your mind', '记得', 'When you remember, you can think of something later.', '记得，就是过后还能想起一件事。', '[{"en":"I remember our trip.","zh":"我记得我们的旅行。"},{"en":"Remember to take a torch.","zh":"记得带手电筒。"}]', NULL, '📝', 3, '["core","action"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-16', 'question', '/ˈkwestʃən/', 'noun', 'words you say when you want to know something', '问题', 'A question asks for an answer.', '问题是在向别人要一个答案。', '[{"en":"I have a question.","zh":"我有一个问题。"},{"en":"That is a good question.","zh":"那是个好问题。"}]', NULL, '❔', 1, '["core","abstract"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-17', 'answer', '/ˈɑːnsə/', 'noun', 'words you say back to a question', '答案', 'An answer is what you say to a question.', '答案就是你对一个问题说的话。', '[{"en":"I know the answer.","zh":"我知道答案。"},{"en":"Your answer is right.","zh":"你的答案是对的。"}]', NULL, '✅', 1, '["core","abstract"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-18', 'science', '/ˈsaɪəns/', 'noun', 'learning about the world by looking and testing', '科学', 'Science helps us learn how things work.', '科学帮助我们了解事物是怎么运作的。', '[{"en":"We learn science at school.","zh":"我们在学校学科学。"},{"en":"Science can explain the rain.","zh":"科学可以解释下雨。"}]', NULL, '🔬', 3, '["thematic","abstract"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-19', 'idea', '/aɪˈdɪə/', 'noun', 'a thought or plan in your mind', '主意；想法', 'An idea is a thought that comes to your mind.', '主意是出现在你脑海里的想法。', '[{"en":"I have an idea.","zh":"我有一个主意。"},{"en":"That is a clever idea.","zh":"那是个聪明的主意。"}]', NULL, '💡', 2, '["core","abstract"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
INSERT INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-20', 'dream', '/driːm/', 'noun', 'pictures in your mind when you sleep', '梦', 'A dream is a story in your mind when you sleep.', '梦是你睡着时脑海里出现的故事。', '[{"en":"I had a dream about a dragon.","zh":"我梦见了一条龙。"},{"en":"My dream was about the sea.","zh":"我的梦是关于大海的。"}]', NULL, '🌙', 2, '["core","abstract","emotional"]', 1793836800000, 1793836800000) ON CONFLICT(id) DO UPDATE SET text=excluded.text, phonetic=excluded.phonetic, part_of_speech=excluded.part_of_speech, meaning_en=excluded.meaning_en, meaning_zh=excluded.meaning_zh, definition_en=excluded.definition_en, definition_zh=excluded.definition_zh, examples=excluded.examples, image=excluded.image, emoji=excluded.emoji, level=excluded.level, tags=excluded.tags, updated_at=excluded.updated_at;
